create extension if not exists pgcrypto;
create type public.customer_source as enum ('walk-in','referral','website');
create type public.loan_status as enum ('active','closed');
create type public.emi_status as enum ('upcoming','paid','partial','overdue','waived');
create type public.service_type as enum ('free_1','free_2','free_3','paid');
create type public.service_status as enum ('upcoming','done','skipped');
create type public.reminder_type as enum ('emi_due','service_due','review_ask','feedback_call','delivery_anniversary','paid_service_nudge');
create type public.reminder_status as enum ('pending','sent','done','snoozed');
create table public.settings (id boolean primary key default true check(id), owner_user_id uuid references auth.users(id), shop_name text not null default 'Biswajit Power Hub', phone text not null default '', address text not null default 'Berhampore, Murshidabad, West Bengal', google_review_link text not null default '', reminder_send_hour int not null default 10 check(reminder_send_hour between 0 and 23), emi_pre_remind_days int not null default 2 check(emi_pre_remind_days between 0 and 30), updated_at timestamptz not null default now());
insert into public.settings(id) values(true) on conflict do nothing;
create or replace function public.is_owner() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.settings where id=true and owner_user_id=auth.uid()); $$;
create table public.customers (id uuid primary key default gen_random_uuid(), name text not null, phone text not null, email text, alt_phone text, address text not null default '', scooter_model text not null, scooter_color text not null default '', chassis_no text, delivery_date date not null, source public.customer_source not null default 'walk-in', created_at timestamptz not null default now());
create index customers_phone_idx on public.customers(phone); create index customers_name_idx on public.customers using gin(to_tsvector('simple',name));
create table public.loans (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id) on delete cascade, company text not null, principal_amount numeric(12,2) not null check(principal_amount>=0), tenure_months int not null check(tenure_months>0), emi_amount numeric(12,2) not null check(emi_amount>=0), emi_day_of_month int not null check(emi_day_of_month between 1 and 31), start_date date not null, status public.loan_status not null default 'active', created_at timestamptz not null default now());
create unique index one_active_loan_per_customer on public.loans(customer_id) where status='active';
create table public.emi_payments (id uuid primary key default gen_random_uuid(), loan_id uuid not null references public.loans(id) on delete cascade, due_date date not null, amount_due numeric(12,2) not null check(amount_due>=0), amount_paid numeric(12,2) not null default 0 check(amount_paid>=0), paid_date date, status public.emi_status not null default 'upcoming', note text, created_at timestamptz not null default now(), unique(loan_id,due_date));
create table public.services (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id) on delete cascade, type public.service_type not null, km_trigger int, month_trigger int, km_last_known int not null default 0, due_date date, status public.service_status not null default 'upcoming', done_date date, done_km int, created_at timestamptz not null default now());
create table public.message_templates (id uuid primary key default gen_random_uuid(), type public.reminder_type not null, name text not null, body_en text not null, body_bn text not null, active boolean not null default true, tone smallint not null default 1, created_at timestamptz not null default now());
create unique index message_template_name_unique on public.message_templates(type,name);
create table public.reminders (id uuid primary key default gen_random_uuid(), type public.reminder_type not null, customer_id uuid not null references public.customers(id) on delete cascade, due_date date not null, status public.reminder_status not null default 'pending', sent_via text not null default 'none' check(sent_via in ('whatsapp','email','none')), sent_at timestamptz, snooze_count int not null default 0 check(snooze_count between 0 and 3), template_id uuid references public.message_templates(id) on delete set null, related_id uuid, occurrence_key text, created_at timestamptz not null default now());
create unique index reminders_occurrence_unique on public.reminders(customer_id,type,occurrence_key) where occurrence_key is not null; create index reminders_due_status_idx on public.reminders(status,due_date);
create table public.appointments (id uuid primary key default gen_random_uuid(), customer_name text not null, phone text not null, date date not null, slot text not null, type text not null check(type in ('free_service','paid_service','test_ride')), status text not null default 'booked', source text not null default 'manual' check(source in ('website','manual')), created_at timestamptz not null default now());
alter table public.settings enable row level security; alter table public.customers enable row level security; alter table public.loans enable row level security; alter table public.emi_payments enable row level security; alter table public.services enable row level security; alter table public.reminders enable row level security; alter table public.message_templates enable row level security; alter table public.appointments enable row level security;
create policy owner_all_settings on public.settings for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy owner_all_customers on public.customers for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy owner_all_loans on public.loans for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy owner_all_emi on public.emi_payments for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy owner_all_services on public.services for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy owner_all_reminders on public.reminders for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy owner_all_templates on public.message_templates for all to authenticated using(public.is_owner()) with check(public.is_owner());
create policy owner_all_appointments on public.appointments for all to authenticated using(public.is_owner()) with check(public.is_owner());
